    private List<String> descendantsAsOf(String sheetId) {
        List<String> ids = descendants(sheetId);
        LocalDate asOf = AsOfContext.current();
        if (asOf != null && !ids.isEmpty()) {
            entities.flush();
            for (String id : ids) {
                snapshots.restore(id, asOf);
